<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api,post,date,fmt} from '../api';import WorkoutChart from '../components/WorkoutChart.vue';import Metrics from '../components/Metrics.vue'
const props=defineProps<{athlete:any}>();const predictions=ref<any[]>([]),workouts=ref<any[]>([]),history=ref<any[]>([]),pid=ref(''),wid=ref(''),prediction=ref<any>(null),scenario=ref('centrale'),selected=ref<any>(null),error=ref(''),busy=ref(false),filter=ref('')
const visible=computed(()=>history.value.filter(h=>!filter.value||h.model_id===filter.value))
const versions=computed(()=>[...new Set(history.value.map(h=>h.model_id))])
const execution=computed(()=>selected.value?Object.fromEntries(Object.entries(selected.value.series).filter(([k])=>['elapsed','target','power','power_mean','power_low','power_high'].includes(k))):null)
const prior=computed(()=>selected.value?Object.fromEntries(Object.entries(selected.value.series).filter(([k])=>['elapsed','hr','hr_chain','hr_low','hr_high'].includes(k))):null)
const diagnostic=computed(()=>selected.value?{elapsed:selected.value.series.elapsed,hr:selected.value.series.hr,hr_real_power:selected.value.series.hr_real_power}:null)
async function load(){predictions.value=await api(`/athletes/${props.athlete.id}/predictions`);workouts.value=await api(`/athletes/${props.athlete.id}/workouts`);history.value=await api(`/athletes/${props.athlete.id}/evaluation`)}
async function choose(){try{prediction.value=await api('/predictions/'+pid.value);scenario.value=prediction.value.scenarios[0].name}catch(e:any){error.value=e.message}}
async function compare(){error.value='';busy.value=true;try{selected.value=await post(`/predictions/${pid.value}/comparisons`,{workout_id:wid.value,scenario:scenario.value});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function open(id:string){try{selected.value=await api('/comparisons/'+id)}catch(e:any){error.value=e.message}}
onMounted(async()=>{try{await load()}catch(e:any){error.value=e.message}})
</script>
<template><div class="page-heading"><div><p class="eyebrow">DOPO L’ALLENAMENTO</p><h1>Verifiche nel tempo</h1><p>Misura l’esecuzione, verifica la previsione, interpreta l’errore.</p></div></div><p class="error" v-if="error">{{error}}</p><section class="card"><h2>Associa un’attività a una previsione</h2><p class="caption">Importa prima il FIT reale nello Storico. La data di importazione non rende prospettica una previsione creata dopo l’allenamento.</p><div class="form-grid"><label>Previsione salvata<select v-model="pid" @change="choose"><option value="">Seleziona…</option><option v-for="p in predictions" :value="p.id">{{p.prescription_original.name}} · {{date(p.created_at)}}</option></select></label><label>Attività reale<select v-model="wid"><option value="">Seleziona…</option><option v-for="w in workouts" :value="w.id">{{date(w.start_time)}} · {{w.source_name}}</option></select></label><label v-if="prediction">Scenario<select v-model="scenario"><option v-for="s in prediction.scenarios" :value="s.name">{{s.name}}</option></select></label></div><button :disabled="!pid||!wid||busy" @click="compare">{{busy?'Confronto in corso…':'Salva confronto'}}</button></section><section class="card" v-if="history.length"><div class="section-heading"><h2>Registro delle verifiche</h2><select v-model="filter"><option value="">Tutte le versioni</option><option v-for="v in versions" :value="v">Versione {{v.slice(0,8)}}</option></select></div><table><thead><tr><th>Confronto</th><th>Qualifica</th><th>MAE HR</th><th>RMSE HR</th><th>Copertura / larghezza HR</th><th>Aderenza MAE P</th><th></th></tr></thead><tbody><tr v-for="h in visible"><td>{{date(h.created_at)}}<small class="block">Modello {{h.model_id.slice(0,8)}}</small></td><td><span class="tag" :class="{good:h.prospective}">{{h.prospective?'Prospettica':'Retrospettiva / già vista'}}</span></td><td>{{fmt(h.metrics.prior.MAE)}} bpm</td><td>{{fmt(h.metrics.prior.RMSE)}} bpm</td><td>{{fmt(h.metrics.prior.coverage)}} / {{fmt(h.metrics.prior.width)}} bpm</td><td>{{fmt(h.adherence.metrics.MAE)}} W</td><td><button class="secondary" @click="open(h.id)">Apri</button></td></tr></tbody></table></section><div v-else class="empty"><h2>La verifica inizia dopo la prima previsione.</h2><p>Salva la previsione prima di partire, poi importa l’attività e associala qui.</p></div><template v-if="selected"><div class="notice">{{selected.prospective?'Verifica prospettica':'Confronto retrospettivo o dati già visti'}} · versione {{selected.model_id.slice(0,8)}}. Il modello non è stato aggiornato.</div><h2>1. Esecuzione della potenza</h2><WorkoutChart v-if="execution" :series="execution" bands/><div class="card"><h3>Aderenza alla prescrizione originale</h3><p>MAE {{fmt(selected.adherence.metrics.MAE)}} W · bias {{fmt(selected.adherence.metrics.bias)}} W · copertura campioni {{fmt(100*selected.adherence.sample_coverage)}}%</p><p>Lavoro sul supporto continuo comune: reale {{fmt(selected.adherence.observed_work_kj_common)}} kJ / prescritto {{fmt(selected.adherence.prescribed_work_kj_common)}} kJ · {{selected.adherence.energy_support_seconds}} secondi osservati.</p><p>Durata reale {{fmt(selected.adherence.registered_duration_s)}} s / prescritta {{selected.adherence.prescribed_duration_s}} s. Sessione intera mantenuta, nessun filtro sui soli blocchi aderenti.</p><details><summary>Scostamenti per blocco</summary><pre>{{JSON.stringify(selected.adherence.blocks,null,2)}}</pre></details></div><h2>2. Previsione HR a priori</h2><p>HR iniziale prevista dallo storico: {{fmt(selected.hr_initial?.predicted_from_train_bpm)}} bpm. Misura all?origine: {{fmt(selected.hr_initial?.observed_at_origin_bpm)}} bpm. Nessuna calibrazione successiva.</p><Metrics :value="selected.metrics.prior" title="Intera sessione · coppie valide"/><WorkoutChart v-if="prior" :series="prior" bands/><h2>3. Diagnostica successiva da potenza reale</h2><p class="warning">Questa curva usa la potenza realmente erogata. Non sostituisce la previsione a priori e non ne dimostra il successo.</p><Metrics :value="selected.metrics.diagnostic"/><WorkoutChart v-if="diagnostic" :series="diagnostic"/><details class="card"><summary>Allineamento, pause, gap e qualità</summary><p>Origine: primo timer start, altrimenti primo campione. Tempo trascorso; nessuna compensazione del ritardo HR. Gap e pause interrompono la diagnostica, con reinizializzazione dai riferimenti train.</p><p>Ripartenze diagnostiche a {{selected.diagnostic_resets_s.join(', ')}} s.</p><pre>{{JSON.stringify({policy:selected.policy,quality:selected.quality,contesto_osservato_non_usato_come_covariata:selected.observed_context},null,2)}}</pre></details></template></template>
